mapper.select:
SELECT * FROM s_ugc_upload WHERE id IN
#{id}
ORDER BY id FOR UPDATE

mapper.update:
UPDATE s_ugc_upload SET status = 'ATTACHED'
WHERE owner_user_id = #{userId} AND status = 'STAGED' AND expires_at > UTC_TIMESTAMP(3)
  AND id IN #{id}

mapper.select:
SELECT * FROM s_post_media WHERE revision_id IN
#{id}
ORDER BY revision_id, position

mapper.update:
UPDATE s_post_media m JOIN s_post_revision r ON r.id = m.revision_id
SET m.cleanup_status = 'PENDING', m.purge_after = #{purgeAfter}
WHERE r.post_id = #{postId} AND m.cleanup_status = 'ACTIVE'

UPDATE s_venue_review_media m JOIN s_venue_review_revision r ON r.id = m.revision_id
SET m.cleanup_status = 'PENDING', m.purge_after = #{purgeAfter}
WHERE r.review_id = #{reviewId} AND m.cleanup_status = 'ACTIVE'
